// Served when the origin cannot answer: a 5xx, or a fetch that throws
// (connection refused, TLS failure, or the subrequest timing out).
//
// WHY THIS EXISTS. The app is one Streamlit process on Community Cloud. Under
// a spike it can stop answering, and what a visitor sees then is Streamlit's
// own connecting spinner, forever, with no explanation -- and a crawler sees
// an error where it previously saw a calculator. A static page that says what
// happened costs nothing to serve, is indexable, and is honest.
//
// Deliberately plain HTML with inline CSS: it must render with no origin, no
// assets and no JavaScript. Anything it references could be the thing that is
// down.
//
// It carries a 503 with Retry-After so crawlers treat it as temporary and come
// back, rather than de-indexing the page.
const BUSY_PAGE = `<!doctype html>
<html lang="en"><head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Busy right now — Worth My Degree</title>
<meta name="robots" content="noindex">
<style>
 body{margin:0;background:#0e1117;color:#fafafa;font:16px/1.6 -apple-system,
   BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;}
 main{max-width:38rem;margin:0 auto;padding:3rem 1.25rem;}
 h1{font-size:1.6rem;line-height:1.25;margin:0 0 .5rem;}
 p{color:#c9ccd4;} a{color:#ff4b4b;}
 .card{border:1px solid #2b3038;border-radius:.6rem;padding:1rem 1.25rem;
   margin:1.5rem 0;background:#161a22;}
 ul{padding-left:1.1rem;color:#c9ccd4;} li{margin:.35rem 0;}
</style></head><body><main>
<h1>🎓 More people than usual are using this right now</h1>
<p>The calculator is temporarily unavailable. Nothing is broken and nothing you
entered was saved — it is one small server, and it is busy.
<a href="/">Try again</a> in a minute.</p>
<div class="card">
<p><strong>What this tool does, while you wait.</strong> It models the real
ten-year financial outcome of a major, school and loan: repayment under the
2026 federal rules, federal and state tax, and cost of living by city, compared
against a debt-free high school graduate.</p>
<ul>
<li>Wages: BLS Occupational Employment and Wage Statistics.</li>
<li>Major outcomes: New York Fed's labor-market survey.</li>
<li>School cost and borrowing: College Scorecard and IPEDS.</li>
</ul>
<p>Free, anonymous, no sign-up. Every figure is computed from published federal
data — an educational estimate, not financial advice.</p>
</div>
<p><a href="/llms.txt">A dense text summary</a> of the whole tool is served
from the edge and is always available.</p>
</main></body></html>`;

// Streamlit-owned path prefixes that must reach the origin unmodified.
// /_stcore carries the websocket (the app's entire runtime) and the
// health endpoint Railway checks.
// /app is Streamlit's static-file mount (enableStaticServing serves repo
// ./static at /app/static) -- without this entry the stray-path 301 folded
// every image URL back to /.
const PASSTHROUGH = ["/_stcore", "/static", "/app/static", "/component", "/media", "/vendor", "/favicon"];

// Of those, the prefixes safe to CACHE at the edge. /static is Streamlit's
// bundle directory and its filenames are content-hashed, so a day of TTL can
// never serve a stale byte -- a redeploy mints new names and the uncached
// HTML shell points at them. This is the single biggest origin-load cut a
// spike can get: without it every new visitor pulled every JS/CSS bundle
// from the origin, which is exactly the multiplication a traffic spike is.
//
// /_stcore must NEVER join this list (websocket + health check), and the
// shell stays uncached for the same version-skew reason the hashes make
// /static safe. /component, /media, /vendor and /favicon are left alone
// until someone verifies their names are immutable too -- caching them on
// an assumption is how a stale asset would outlive a deploy.
// Per-prefix, because the two cacheable families age differently. /static
// bundles are content-hashed -- a day plus `immutable` can never serve a
// stale byte. /app/static is Streamlit's static-file feature carrying the
// marketing images (repo ./static, see static/README.md), whose NAMES DO NOT
// CHANGE when the content does -- an hour, no immutable, so a regenerated
// poster propagates within the hour instead of within a day.
const EDGE_CACHED = [
  { prefix: "/static", ttl: 86400, immutable: true },
  { prefix: "/app/static", ttl: 3600, immutable: false },
];

// A cacheable static asset, stored through the Cache API so that WE decide what
// gets kept, on the way in AND on the way out.
//
// The previous version passed `cf: { cacheEverything: true, cacheTtl }` to
// fetch(), which tells the edge to store the response WHATEVER ITS STATUS. The
// 2xx guard sat below that call and only chose the cache-control header handed
// back to the browser, so a 404 or a 502 from the origin was pinned at the edge
// for the full TTL -- an hour for /app/static. The comment there stated the
// right rule ("caching an origin error would outlive the outage that caused
// it") and the code applied it in the one place it could not take effect.
//
// It is not a hypothetical failure and it is not rare: it fires whenever a page
// referencing a new asset goes live before the asset does, which is the normal
// order here, because the guide HTML ships with `npx wrangler deploy` and the
// images ship with a git push to Streamlit Cloud. Verifying the deploy is
// enough to trigger it. That is exactly how it was found, on 2026-08-12: the
// counselor guide's hero 404ed for an hour after the images were demonstrably
// present at the origin, and the same URL with a query string appended -- a
// different cache key -- returned the image immediately.
//
// Three properties worth keeping:
//
//   1. ONLY 2xx IS STORED. Anything else goes back to the visitor and is
//      forgotten, so the next request re-asks the origin.
//   2. A NON-2xx ALREADY IN THE CACHE IS DROPPED, not served. This is what
//      heals entries the old code pinned, without a purge: the first request
//      after this deploys evicts the bad entry and refetches. Without it the
//      fix would only stop NEW poisoning and leave the existing hour to run.
//   3. `cacheTtlByStatus` would express (1) declaratively and is documented as
//      Enterprise-only, so it is deliberately not used here.
//
// Failure is still a bare 503 rather than Cloudflare's 1101 page, and the
// websocket never reaches this function -- /_stcore returns above it.
async function serveCachedAsset(request, ctx, policy) {
  const cache = caches.default;
  // The Cache API keys on GET. A HEAD still passes through, just uncached.
  const cacheable = request.method === "GET";

  if (cacheable) {
    const hit = await cache.match(request);
    if (hit && hit.ok) {
      return hit;
    }
    if (hit) {
      ctx.waitUntil(cache.delete(request));
    }
  }

  let resp;
  try {
    resp = await fetch(request);
  } catch (err) {
    return new Response(null, {
      status: 503,
      headers: { "retry-after": "60", "cache-control": "no-store" },
    });
  }
  if (!cacheable || !resp.ok) {
    return resp;
  }

  // Assert the policy on the response, so the browser holds the asset as long
  // as the edge does. cache.put() reads this same header for its own TTL, so
  // the two cannot disagree.
  const out = new Response(resp.body, resp);
  out.headers.set("cache-control",
    `public, max-age=${policy.ttl}` + (policy.immutable ? ", immutable" : ""));
  // clone() before put(): a body can only be read once, and put() consumes it.
  // put() rejects some responses outright (a Set-Cookie, a 206); catching keeps
  // an uncacheable asset serving rather than failing the request for it.
  ctx.waitUntil(cache.put(request, out.clone()).catch(() => {}));
  return out;
}

function busyResponse() {
  return new Response(BUSY_PAGE, {
    status: 503,
    headers: {
      "content-type": "text/html; charset=utf-8",
      // Temporary, and say so: a crawler that reads 503 + Retry-After comes
      // back rather than dropping the page from its index.
      "retry-after": "60",
      "cache-control": "no-store",
    },
  });
}

// Landing-page counting, written to the SAME Supabase table the app logs to,
// so the admin page reads it with the machinery it already has.
//
// SERVER-SIDE ON PURPOSE. The obvious alternative -- a beacon script in the
// page -- would put an external reference on a page whose entire value is
// that it references nothing and therefore renders when the origin is down.
// This runs in the Worker AFTER the response is already on its way
// (ctx.waitUntil), so the visitor's browser makes zero extra requests and
// waits for nothing.
//
// Needs two secrets, set once per deploy:
//     npx wrangler secret put SUPABASE_URL
//     npx wrangler secret put SUPABASE_ANON_KEY
// Absent either, logging is skipped silently -- a missing secret must cost a
// statistic, never a page.
const LANDING_ACTION = "landing_view";
// Guide reads. Without these a like count has no denominator: 14 reactions
// means something very different against 20 readers than against 2,000.
const GUIDE_ACTION = "guide_view";
const LANDING_LOG_TIMEOUT_MS = 2500;

// Crude on purpose, and stated as such: a user-agent substring match catches
// the declared crawlers (which are most of the volume) and nothing else. It
// exists so the landing count is not mostly Googlebot; it is not a bot
// defence and must not be read as one.
const BOT_UA = /bot|crawl|spider|slurp|bingpreview|facebookexternalhit|headless|lighthouse|pingdom|uptime/i;

// Article reactions. Same table, same idiom as the landing rows:
// "article_like:slug=<slug>" in usage_logs, session_id NULL.
//
// NOT A MEASUREMENT. There is no identity here -- the browser guard is
// localStorage, which anyone can clear, and nothing stops a script POSTing in
// a loop. It is a warm signal for deciding what to write next, and it must
// never be used as data. It stays out of PAGEVIEW_ACTIONS for the same reason
// landing rows do.
const LIKE_ACTION = "article_like";

// Shares, same table, same idiom: "article_share:slug=<slug>".
//
// Weaker than a like, and the weakness is specific rather than general. It is
// written when the browser's share sheet RESOLVES or the link reaches the
// clipboard -- neither of which proves the article was sent to anybody. Some
// browsers resolve navigator.share on invoke rather than on delivery, and a
// copied link can be pasted nowhere. There is also no dedupe: a second share
// is a second row, because sharing a guide with two people twice is a real
// thing a reader does and localStorage cannot tell that apart from a fidget.
//
// So: an upper bound on intent to pass a guide on, and never a count of
// people. Everything LIKE_ACTION's comment says applies here with less
// confidence, not more.
const SHARE_ACTION = "article_share";

function jsonResponse(body, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { "content-type": "application/json; charset=utf-8",
               "cache-control": "no-store" },
  });
}

// Slugs are ours, but this endpoint is public: without a shape check a POST
// could write arbitrary text into usage_logs.action -- the same injection the
// app's NAV_ORIGINS validation exists to stop.
//
// TWO NAMESPACES, checked separately. A guide slug is a routed path and can be
// recovered from the GUIDES map; the charts are a single page, so their slugs
// are injected as CHART_SLUGS beside it. Falling back to the guide check for
// an unrecognised kind is deliberate: an old cached page posts no `kind` at
// all, and it means a guide.
function knownSlug(slug, kind) {
  if (typeof slug !== "string") return false;
  if (kind === "chart") return CHART_SLUGS.includes(slug);
  return Object.hasOwn(GUIDES, `/guides/${slug}`);
}

// A chart like is not an article like, and pooling them would make the two
// unseparable after the fact for no gain -- they are different objects with
// different slugs and different reasons for being liked. Distinct actions
// need no DDL (usage_logs.action is free text) but DO need adding to app.py's
// EDGE_ACTION_PREFIXES, or these rows read as app activity on the admin page.
const CHART_LIKE_ACTION = "chart_like";
const CHART_SHARE_ACTION = "chart_share";

async function likeCount(env, slug, action) {
  const query = `${env.SUPABASE_URL}/rest/v1/usage_logs` +
    `?action=eq.${encodeURIComponent(`${action}:slug=${slug}`)}` +
    `&select=action`;
  const resp = await fetch(query, {
    headers: {
      apikey: env.SUPABASE_ANON_KEY,
      authorization: `Bearer ${env.SUPABASE_ANON_KEY}`,
      // The count in a header rather than the rows themselves -- a body that
      // grew with every like would eventually be the slowest thing on the page.
      prefer: "count=exact",
      range: "0-0",
    },
    signal: AbortSignal.timeout(LANDING_LOG_TIMEOUT_MS),
  });
  const range = resp.headers.get("content-range") || "";
  const total = parseInt(range.split("/")[1], 10);
  return Number.isFinite(total) ? total : null;
}

// Same exclusions the app applies to itself. ?test=1 is the developer flag;
// src=selftest is the production-verification tag.
//
// SHARED WITH THE REACTION ENDPOINTS, which is new (2026-08-13). They had no
// exclusion at all: tapping Helpful while verifying production wrote a real
// row with nothing marking it as the author's, which is the contamination
// CLAUDE.md records for pageviews, landing in a per-guide count instead. That
// needs the page's query string to reach the POST -- see the article template.
//
// The reads are deliberately NOT excluded. A count is a read, it writes
// nothing, and blanking it in test mode would hide the very thing being
// verified.
function excludedFromLogging(request, url) {
  const src = url.searchParams.get("src");
  if (url.searchParams.get("test") === "1" || src === "selftest") return true;
  return BOT_UA.test(request.headers.get("user-agent") || "");
}

// One row, one action string. Extracted when shares arrived so the two
// reactions cannot drift into writing differently shaped rows -- the traffic
// source, the null session and the timestamp format are properties of an edge
// row, not of a like.
async function insertReaction(env, url, action, slug) {
  await fetch(`${env.SUPABASE_URL}/rest/v1/usage_logs`, {
    method: "POST",
    headers: {
      "content-type": "application/json",
      apikey: env.SUPABASE_ANON_KEY,
      authorization: `Bearer ${env.SUPABASE_ANON_KEY}`,
      prefer: "return=minimal",
    },
    body: JSON.stringify({
      timestamp: new Date().toISOString(),
      session_id: null,
      traffic_source: url.searchParams.get("src") || null,
      action: `${action}:slug=${slug}`,
    }),
    signal: AbortSignal.timeout(LANDING_LOG_TIMEOUT_MS),
  });
}

// The slug arrives in a JSON body on both reaction endpoints.
async function postedBody(request) {
  try {
    const body = await request.json();
    return { slug: body.slug, kind: body.kind };
  } catch (err) {
    return { slug: null, kind: null };   // falls through to the shape check
  }
}

async function handleShare(request, env, url) {
  // No GET half, deliberately: a share count is not shown to the reader. The
  // number is for deciding what to write next, and putting it on the page
  // would turn a soft signal into social proof -- a guide nobody has passed on
  // yet would read as one nobody thought worth passing on.
  if (!env || !env.SUPABASE_URL || !env.SUPABASE_ANON_KEY) {
    return jsonResponse({ error: "not configured" }, 503);
  }
  if (request.method !== "POST") return jsonResponse({ error: "method" }, 405);
  const { slug, kind } = await postedBody(request);
  if (!knownSlug(slug, kind)) return jsonResponse({ error: "unknown slug" }, 404);
  // A self-test share gets the same answer a real one does, and writes
  // nothing. The reader (who is the author) must not be able to tell, or the
  // thing being verified is no longer the thing that ships.
  if (excludedFromLogging(request, url)) return jsonResponse({ ok: true });
  try {
    await insertReaction(env, url,
      kind === "chart" ? CHART_SHARE_ACTION : SHARE_ACTION, slug);
  } catch (err) {
    // The reader's share already happened; a failed write is a lost statistic
    // and must not become an error on their screen. Same trade as logEdgeView.
  }
  return jsonResponse({ ok: true });
}

async function handleLike(request, env, url) {
  if (!env || !env.SUPABASE_URL || !env.SUPABASE_ANON_KEY) {
    return jsonResponse({ error: "not configured" }, 503);
  }
  if (request.method === "GET") {
    const slug = url.searchParams.get("slug");
    // The GET carries its kind on the query string, because there is no body
    // to put it in. Absent, it means a guide -- see knownSlug.
    const getKind = url.searchParams.get("kind");
    if (!knownSlug(slug, getKind)) return jsonResponse({ error: "unknown slug" }, 404);
    try {
      return jsonResponse({ count: await likeCount(env, slug,
        getKind === "chart" ? CHART_LIKE_ACTION : LIKE_ACTION) });
    } catch (err) {
      return jsonResponse({ error: "unavailable" }, 503);
    }
  }
  if (request.method !== "POST") return jsonResponse({ error: "method" }, 405);
  const { slug, kind } = await postedBody(request);
  if (!knownSlug(slug, kind)) return jsonResponse({ error: "unknown slug" }, 404);
  try {
    // The count is still returned on an excluded tap, so the button behaves
    // identically -- it just leaves no row.
    const action = kind === "chart" ? CHART_LIKE_ACTION : LIKE_ACTION;
    if (!excludedFromLogging(request, url)) {
      await insertReaction(env, url, action, slug);
    }
    return jsonResponse({ count: await likeCount(env, slug, action) });
  } catch (err) {
    // The visitor already saw the button acknowledge them; a failed write is
    // not worth an error state on an article they are still reading.
    return jsonResponse({ count: null });
  }
}

async function logEdgeView(request, env, url, action) {
  if (!env || !env.SUPABASE_URL || !env.SUPABASE_ANON_KEY) return;

  const src = url.searchParams.get("src");
  if (excludedFromLogging(request, url)) return;

  // The event:k=v shape analyze_survey.py already parses. path= separates a
  // typed bare domain from a clicked marketing link, which the src tag alone
  // cannot: a /welcome hit whose tag went missing is a different story from
  // someone who typed the name.


  // UTC, not visitor-local. isoformat() in the app emits an offset and this
  // emits Z; both are correct absolute instants, which is all daily bucketing
  // needs (traffic_report_dates converts before it buckets). The edge knows
  // the visitor's timezone but constructing a local ISO string from an IANA
  // name here would be guesswork for no gain.
  //
  // session_id is NULL because an edge landing HAS no session -- no Streamlit
  // run, no browser state. CLAUDE.md's rule for NULL session_id is "exclude
  // from joins rather than treat as one shared session", which is exactly the
  // right treatment here.
  const row = {
    timestamp: new Date().toISOString(),
    session_id: null,
    traffic_source: src || null,
    action,
  };

  try {
    await fetch(`${env.SUPABASE_URL}/rest/v1/usage_logs`, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        apikey: env.SUPABASE_ANON_KEY,
        authorization: `Bearer ${env.SUPABASE_ANON_KEY}`,
        prefer: "return=minimal",
      },
      body: JSON.stringify(row),
      signal: AbortSignal.timeout(LANDING_LOG_TIMEOUT_MS),
    });
  } catch (err) {
    // Swallowed deliberately: the response has already been returned, and a
    // database that is slow or down must not turn into a Worker exception.
  }
}

function logLanding(request, env, url) {
  return logEdgeView(request, env, url,
    `${LANDING_ACTION}:path=${url.pathname === "/" ? "root" : "welcome"}`);
}

function logGuide(request, env, url, slug) {
  return logEdgeView(request, env, url, `${GUIDE_ACTION}:slug=${slug}`);
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    // 1. Host + scheme canonicalization, path and query preserved.
    if (url.hostname !== "worthmydegree.com" || url.protocol === "http:") {
      url.hostname = "worthmydegree.com";
      url.protocol = "https:";
      return Response.redirect(url.toString(), 301);
    }

    // 2. Edge-served text artifacts.
    const text = TEXT_FILES[url.pathname];
    if (text) {
      return new Response(text[1], {
        headers: {
          "content-type": `${text[0]}; charset=utf-8`,
          "cache-control": "public, max-age=3600",
        },
      });
    }

    // 2b. The static landing page -- THE FRONT DOOR since 2026-08-11.
    //
    // A bare, parameter-less "/" serves it: someone typing the domain gets
    // the instant edge page, and "Open the calculator" is one click. Any
    // query string at all goes straight to the app instead, which is what
    // keeps every existing link working unchanged: share links, ?src= tags,
    // ?tool= pages and ?admin= all carry params by construction. The
    // landing's own CTAs point at "/?go=1" -- a marker with no meaning to
    // the app -- precisely so a click-through has a param and cannot loop
    // back here.
    //
    // /welcome stays as an alias (marketing links already point there, WITH
    // src params, and must keep landing here rather than falling through to
    // the app). Both spellings canonicalize to "/", so search engines see
    // one page.
    //
    // CONSEQUENCE FOR THE RESEARCH DATA, recorded in migrations.sql: from
    // this date the app's `pageview` rows are clicked-through visitors, not
    // raw arrivals -- organic traffic gained one click of funnel.
    const isLanding =
      (url.pathname === "/" && url.search === "") ||
      url.pathname === "/welcome" || url.pathname === "/welcome/";
    if (isLanding) {
      const page = new Response(LANDING, {
        headers: {
          "content-type": "text/html; charset=utf-8",
          "cache-control": "public, max-age=3600",
          "link": `<${CANON}/>; rel="canonical"`,
        },
      });
      // AFTER the response. waitUntil keeps the invocation alive for the
      // insert without delaying a single byte to the visitor.
      if (ctx && typeof ctx.waitUntil === "function") {
        ctx.waitUntil(logLanding(request, env, url));
      }
      return page;
    }

    // 2c. Guides -- static article pages, built from content/posts by
    // infra/build_site.py. Cached an hour like the landing: long enough to
    // absorb a spike, short enough that a correction propagates the same day.
    const guidePath = url.pathname.replace(/\/$/, "") || "/";
    const guide = GUIDES[guidePath];
    if (guide) {
      if (ctx && typeof ctx.waitUntil === "function") {
        ctx.waitUntil(logGuide(request, env, url,
          guidePath === "/guides" ? "index" : guidePath.split("/").pop()));
      }
      return new Response(guide, {
        headers: {
          "content-type": "text/html; charset=utf-8",
          "cache-control": "public, max-age=3600",
          "link": `<${CANON}${url.pathname.replace(/\/$/, "")}>; rel="canonical"`,
        },
      });
    }

    // 2d. The reaction endpoints. First-party on purpose: the article pages
    // call our own origin, so they still reference nothing external.
    if (url.pathname === "/api/like" || url.pathname === "/api/likes") {
      return handleLike(request, env, url);
    }
    if (url.pathname === "/api/share") {
      return handleShare(request, env, url);
    }

    // 3. Streamlit internals: passthrough, cached at the edge where safe.
    if (PASSTHROUGH.some((p) => url.pathname.startsWith(p))) {
      // The websocket must stay a bare fetch: wrapping it or buffering its
      // response is how you hang every session at once, per the note on
      // step 5. Everything else gets a guard so a dead origin during a spike
      // degrades to a clean 503 instead of Cloudflare's own 1101 error page.
      // A bare 503, not BUSY_PAGE -- these are asset requests, and an HTML
      // apology where a script was expected is a second error, not a message.
      if (url.pathname.startsWith("/_stcore")) {
        return fetch(request);
      }
      const cached = EDGE_CACHED.find((p) => url.pathname.startsWith(p.prefix));
      if (cached) {
        return serveCachedAsset(request, ctx, cached);
      }
      try {
        const resp = await fetch(request);
        return resp;
      } catch (err) {
        return new Response(null, {
          status: 503,
          headers: { "retry-after": "60", "cache-control": "no-store" },
        });
      }
    }

    // 4. The app has exactly one route; fold stray paths into it.
    if (url.pathname !== "/") {
      return Response.redirect(CANON + "/" + url.search, 301);
    }

    // 5. Serve the shell with canonical + JSON-LD + description injected.
    //
    // The origin call is guarded from here down. A spike shows up as a 5xx or
    // a throw, and either one used to become Streamlit's bare spinner; now it
    // becomes a page that says what happened. Only the HTML DOCUMENT is
    // substituted -- /_stcore returned above, untouched, because breaking the
    // websocket is how you hang a session that would otherwise have recovered.
    let resp;
    try {
      resp = await fetch(request);
    } catch (err) {
      return busyResponse();
    }
    if (resp.status >= 500) return busyResponse();
    const ctype = resp.headers.get("content-type") || "";
    if (!ctype.includes("text/html")) return resp;

    const canonical = canonicalFor(url);
    const rewritten = new HTMLRewriter()
      .on("head", {
        element(head) {
          head.append(`<link rel="canonical" href="${canonical}">`, { html: true });
          head.append(`<meta name="description" content="${META_DESC}">`, { html: true });
          // The social preview card. og:image points at the feature graphic
          // served from /app/static (see static/README.md -- renaming that
          // file breaks this tag). Every link posted to FB/LinkedIn/Slack
          // renders this card, whether or not the poster attached anything.
          head.append(`<meta property="og:type" content="website">`, { html: true });
          head.append(`<meta property="og:title" content="Is the degree worth the loan? — worthmydegree.com">`, { html: true });
          head.append(`<meta property="og:description" content="${META_DESC}">`, { html: true });
          head.append(`<meta property="og:url" content="${canonical}">`, { html: true });
          head.append(`<meta property="og:image" content="${CANON}/app/static/feature-og-1200x630.png">`, { html: true });
          head.append(`<meta property="og:image:width" content="1200">`, { html: true });
          head.append(`<meta property="og:image:height" content="630">`, { html: true });
          head.append(`<meta name="twitter:card" content="summary_large_image">`, { html: true });
          head.append(`<meta name="twitter:image" content="${CANON}/app/static/feature-og-1200x630.png">`, { html: true });
          head.append(`<script type="application/ld+json">${JSONLD}</script>`, { html: true });
        },
      })
      .transform(resp);

    const headers = new Headers(rewritten.headers);
    headers.append("Link", `<${canonical}>; rel="canonical"`);
    return new Response(rewritten.body, { status: rewritten.status, headers });
  },
};
